contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take inputs matching C.transfer signature. v can be any uint.
    // _tos must be non-empty to pass the require in C.transfer; we enforce that here.
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        // We want to observe whether c.transfer reverts or returns true.
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule: C.transfer never returns false; it either returns true (when it completes all calls)
        // or it reverts. Therefore, if it did not revert, the returned value must be true.
        assert(reverted || ret == true);
    }

    receive() external payable {}
}

