contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function taking inputs that drive C.transfer
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        // require non-empty tos so C.transfer's initial require passes
        require(_tos.length > 0);

        // record this contract balance before calling
        uint before = address(this).balance;

        bool reverted;
        bool ret;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }

        // General rule: if the call did not revert, it must have returned true
        // and the call must not have changed this test contract's balance.
        assert(reverted || (ret == true && address(this).balance == before));
    }

    receive() external payable {}
}

